def find_duplicates_slow(orders: list[dict]) -> list[dict]:
    duplicates = []
    for i, order in enumerate(orders):
        for other in orders[:i]:  # O(n^2) : compare chaque paire
            if order["key"] == other["key"]:
                duplicates.append(order)
                break
    return duplicates

def find_duplicates_fast(orders: list[dict]) -> list[dict]:
    seen: dict[str, dict] = {}
    duplicates = []
    for order in orders:  # O(n) : une seule passe, recherche en O(1)
        if order["key"] in seen:
            duplicates.append(order)
        else:
            seen[order["key"]] = order
    return duplicates
